import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 21 · everyday recipe: chicken and dumplings
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, when anybody in our family was sick, or sad, or had a new baby, or lost somebody, Grandma Pearl showed up at the door with a big enamel pot wrapped in a towel. Chicken and dumplings. She never called first, she never asked what you needed. She just knew. And I've done the same thing for sixty years, because there is nothing a pot of chicken and dumplings can't make a little better.""",
   "chicken and dumplings pot steam", "SHE NEVER CALLED FIRST")
sc("""But today, when young people make dumplings, they come out heavy and gummy, like wet paste, or they fall apart in the broth until it's just cloudy soup. So tonight I'm giving you Grandma Pearl's recipe. Light, fluffy dumplings on top of a rich chicken broth. Every step, and the four mistakes that make dumplings gummy. It feeds six, and it costs less than a fast food lunch for two.""",
   "fluffy dumplings broth bowl", "NOT LIKE WET PASTE")

ch("Pearl's kitchen")
sc("""Grandma Pearl grew up on a farm outside Mansfield, and during the Depression a chicken had to feed nine people. So nothing was wasted. The broth came from the bones, the fat went in the dumplings, and the leftover broth was soup the next day. She used to say, a chicken in the pot is worth two on the table.""",
   "1930s farm kitchen woman cooking", "NOTHING WAS WASTED")
sc("""She made her dumplings without measuring a single thing, by feel. It took me thirty years to write it down properly. I stood next to her in nineteen sixty-eight with a notebook and a measuring cup, and every time she grabbed a handful of flour, I made her drop it in the cup first. She thought I was the silliest girl in Ohio. But that's why I can give it to you tonight.""",
   "handwritten recipe notebook kitchen", "BY FEEL")

sc("""The first time I made them myself was the winter of nineteen sixty-six, for my husband, who had the flu. I lifted the lid three times to check, and they came out like hockey pucks. He ate every one and said they were wonderful, because he was a good man and he had a fever. The next week I went straight to Pearl's kitchen with my notebook.""",
   "1960s young couple kitchen winter", "LIKE HOCKEY PUCKS")

ch("What you need")
sc("""For the chicken, honey. About three pounds of chicken pieces with the bone and skin. Thighs and legs are best, they have the most flavor and they don't dry out. One onion, two carrots, two stalks of celery, a bay leaf, a teaspoon of salt and some pepper. And about ten cups of water, enough to cover everything.""",
   "raw chicken thighs vegetables cutting board", "BONES AND SKIN")
sc("""For the dumplings. Two cups of flour. One tablespoon of baking powder. One teaspoon of salt. Three tablespoons of cold butter, or chicken fat skimmed from the pot like Pearl did. And about three quarters of a cup of cold milk. That's all. Not one thing fancy.""",
   "flour baking powder milk butter bowl", "NOTHING FANCY")

sc("""You can use a whole chicken cut up, or a store rotisserie chicken if you're in a hurry, sweetheart. Pearl would never forgive me for saying that. But on a busy Tuesday, pull the meat off a rotisserie chicken, simmer the bones for forty minutes in a box of store broth with the vegetables, and you'll have supper in an hour. Not as good as hers, but close enough to make a sick child smile.""",
   "rotisserie chicken store kitchen", "A BUSY TUESDAY")

ch("The broth")
sc("""Step one. Put the chicken in your biggest pot with the onion cut in quarters, one carrot, one stalk of celery, the bay leaf, the salt and pepper. Cover it with the cold water. Bring it to a boil, then turn it down to a gentle simmer, little bubbles, and leave it alone for an hour with the lid tilted. Skim off the gray foam that comes up in the first ten minutes.""",
   "chicken simmering pot stove", "LITTLE BUBBLES")
sc("""Step two. Take the chicken out and let it cool on a plate. Pour the broth through a strainer and throw out the tired vegetables. They gave everything they had. When the chicken is cool enough, pull the meat off the bones in big bites and throw away the skin and bones. Now chop the other carrot and celery fresh, and put them back in the broth to cook for ten minutes.""",
   "shredded chicken plate kitchen", "THE TIRED VEGETABLES")
sc("""And here's Pearl's trick for a broth that tastes like Sunday. Before you add anything back, taste it. Most people under-salt their broth, and then the dumplings taste like nothing. Add salt a little at a time until it tastes good enough to drink from a cup. That's how you know it's right. She always made me drink a little cup of it, and I still do.""",
   "cup of chicken broth steam", "GOOD ENOUGH TO DRINK")
sc("""Then make it a little thicker, so it's a gravy and not a soup. Shake two tablespoons of flour with half a cup of cold water in a jar, the same trick as my gravy, and stir it into the simmering broth. Add the chicken back in, and a splash of milk or cream if you like it richer. Keep it at a gentle bubble, never a hard boil.""",
   "stirring creamy chicken stew pot", "A GRAVY, NOT A SOUP")

ch("The dumplings")
sc("""Step three, the dumplings. Stir the flour, baking powder and salt in a bowl. Cut the cold butter in with two knives or your fingertips, until it looks like coarse crumbs. Then pour in the cold milk and stir with a fork, just until it comes together into a shaggy, sticky dough. Ten or twelve stirs. Stop. Lumps are fine. Lumps are good.""",
   "dumpling dough bowl fork", "LUMPS ARE GOOD")
sc("""Step four. Drop the dough by big spoonfuls on top of the bubbling stew, about the size of a golf ball, close together but not touching. They'll double in size. Use two spoons, one to scoop and one to push it off. Dip the spoons in the hot broth first so the dough slides right off.""",
   "dropping dumplings into stew spoon", "THE SIZE OF A GOLF BALL")
sc("""Step five, the most important one. Put the lid on tight and cook for fifteen minutes, and do not lift that lid. Not once. Not to peek. The dumplings cook in the steam, and every time you lift the lid, the steam escapes and they go heavy. Grandma Pearl would slap your hand away from the pot. She said, a watched dumpling never rises.""",
   "pot lid closed stove simmering", "DON'T LIFT THE LID")
sc("""After fifteen minutes, lift the lid and poke one dumpling with a toothpick, right in the middle. If it comes out clean, they're done. If it's wet, put the lid back on for three more minutes. They should be fluffy and light inside, like a biscuit, and a little bit glossy on top from the steam.""",
   "fluffy dumplings in pot", "LIKE A BISCUIT INSIDE")

sc("""Some people like rolled dumplings instead, flat like noodles, the way they make them down South. Same dough with a little less baking powder, rolled thin on a floured counter and cut into strips. Drop them in one at a time and stir gently. Pearl made the fluffy ones, but our neighbor Mrs. Hollis was from Kentucky, and she made the flat ones, and those two women argued about it over the fence for twenty years.""",
   "rolled dumplings strips flour counter", "TWENTY YEARS OF ARGUING")

ch("Four mistakes")
sc("""So the four mistakes, sweetheart. Mistake one. Stirring the dough too much. If you beat it smooth, you get tough, gummy dumplings. A few stirs and stop. Mistake two. Warm butter and warm milk. Cold makes the little pockets that puff up. Keep them in the icebox until the second you use them.""",
   "mixing dough bowl kitchen", "A FEW STIRS AND STOP")
sc("""Mistake three. A broth that isn't bubbling. If you drop the dough into broth that's just warm, the dumplings soak it up and turn to mush. It has to be at a steady simmer. And mistake four, lifting the lid. I know I already said it. I'm saying it again because everybody does it.""",
   "simmering broth bubbles close up", "EVERYBODY DOES IT")

sc("""And one more thing about the pot, honey. Use a wide pot, not a tall narrow one. The dumplings need room on top to spread and rise. If they're crowded, the ones in the middle stay raw while the ones on the edge get mushy. Pearl's enamel pot was so wide it covered two burners, and it's in my pantry today.""",
   "wide enamel pot stove vintage", "A WIDE POT")

ch("Serving it")
sc("""Serve it in deep bowls, a few dumplings on top of the chicken and broth, with black pepper and a little chopped parsley if you have it. In our house we had it with a plate of sliced tomatoes in summer, or applesauce in winter. And always on a cold night, with the windows fogged up from the steam.""",
   "chicken dumplings bowl parsley", "WINDOWS FOGGED UP")
sc("""Leftovers keep three days in the icebox, but the dumplings soak up the broth overnight. So warm it slowly with a little extra water or broth, and stir gently. My father liked it better the second day. He said the dumplings had time to think about it.""",
   "leftover stew reheating pot", "TIME TO THINK ABOUT IT")
sc("""And if you want to do what Pearl did, make a double pot and take half to somebody who needs it. Wrap the pot in a towel, put it in a box so it doesn't tip in the car, and leave it on the porch if they're not up for company. Don't call first. Just knock and go.""",
   "pot wrapped towel porch door", "JUST KNOCK AND GO")

ch("Grandma's kitchen")
sc("""So one more time, honey. Bone-in chicken simmered an hour. Strain the broth, salt it until it's good enough to drink, and thicken it a little. Cold butter, cold milk, a few stirs. Drop them on a bubbling pot, lid on tight, fifteen minutes, no peeking. That's Grandma Pearl's chicken and dumplings, and they have never once been gummy.""",
   "chicken and dumplings dinner table", "NEVER GUMMY")
sc("""Tell me in the comments, sweetheart. Who in your family made the dish everybody got when they were sick? I read every comment, and tomorrow I'll bring you another one from my kitchen. Good night, honey.""",
   "warm kitchen evening window", "WHO MADE YOURS?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma21", "The Chicken and Dumplings EVERYONE's Grandma Made (Why Yours Turn GUMMY)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Recipe as written by Grandma Ruth: 3 lb bone-in chicken, onion, 2 carrots, 2 celery stalks, bay leaf, 10 cups water, simmer 1 hour; dumplings 2 cups flour, 1 tbsp baking powder, 1 tsp salt, 3 tbsp cold butter, 3/4 cup cold milk; covered 15 minutes."],
     "everyday recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
